export const COLORS={original:{name:'Paleta da foto',swatch:'linear-gradient(135deg,#e7d2a7,#c97f9c,#799475)'},yellow:{name:'Amarelo',swatch:'#edc33c'},pink:{name:'Rosa',swatch:'#d98ca8'},white:{name:'Branco',swatch:'#f4f0e7'},red:{name:'Vermelho',swatch:'#a43a43'},lilac:{name:'Lilás',swatch:'#b5a0cc'}};
for(const product of PRODUCTS)product.colors=product.id==='sunflower'?['original','yellow','white','pink']:['original','yellow','pink','white','red','lilac'];
export const SIZES={petite:{name:'Pequeno',extra:0,stems:'12–15 hastes',dimensions:'28 cm de largura × 38 cm de altura',description:'Um gesto delicado e compacto. Perfeito para a mesa de cabeceira.'},classic:{name:'Médio',extra:20,stems:'20–25 hastes',dimensions:'38 cm de largura × 45 cm de altura',description:'Um buquê generoso para o dia a dia. É o tamanho mostrado nas fotos.'},abundant:{name:'Grande',extra:40,stems:'30–35 hastes',dimensions:'48 cm de largura × 55 cm de altura',description:'Um arranjo exuberante para iluminar o ambiente e marcar o momento.'}};
export const money = value => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value);
export const getProduct=id=>PRODUCTS.find(p=>p.id===id);
export const escapeHtml = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
export function today(now=new Date()) {return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
export function addDays(iso,n){const d=new Date(iso+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
export function prettyDate(iso){return new Intl.DateTimeFormat('pt-BR',{weekday:'short',month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(iso+'T12:00:00Z'));}
export function dateStatus(iso,product,now=new Date()) {
  const base=today(now);
  if(!/^\d{4}-\d{2}-\d{2}$/.test(iso)||Number.isNaN(Date.parse(iso+'T12:00:00Z'))||new Date(iso+'T12:00:00Z').toISOString().slice(0,10)!==iso)return 'Escolha uma data de entrega.';
  if(iso<addDays(base,product.lead))return `Este buquê precisa de ${product.lead} dias de preparação. Escolha uma data posterior.`;
  if(iso>addDays(base,30))return 'Escolha uma data dentro dos próximos 30 dias.';
  const day=new Date(iso+'T12:00:00Z').getUTCDay();
  if(day===0||day===1)return 'Nosso estúdio demonstrativo fecha aos domingos e às segundas-feiras.';
  if(iso===addDays(base,10))return 'Esta data está lotada na simulação. Escolha outro dia.';
  return '';
}
export function datesFor(product,now=new Date()){return Array.from({length:29},(_,i)=>{const date=addDays(today(now),i+2);return {date,reason:dateStatus(date,product,now)};});}
export function deliveryFor(zip){const value=String(zip).trim();if(!/^\d{5}$/.test(value))return {ok:false,message:'Informe um código postal dos EUA (ZIP) com 5 dígitos, como 97201.'};if(!['97201','97202','97203','97204','97205','97206'].includes(value))return {ok:false,message:'Não entregamos neste código postal na área demonstrativa. Tente 97201–97206, em Portland. Nenhuma cobrança foi feita.'};const fee=['97201','97202'].includes(value)?6:9;return {ok:true,zip:value,fee,message:`Você está na nossa área demonstrativa de entrega. ${money(fee)} por buquê · das 9h às 18h nas datas disponíveis.`};}
export function unitPrice(item){const p=getProduct(item.product);return p.price+SIZES[item.size].extra+(item.vase?18:0);}
export function bagTotals(bag){const subtotal=bag.reduce((n,item)=>n+unitPrice(item)*item.quantity,0),delivery=bag.reduce((n,item)=>n+(deliveryFor(item.zip).fee||0)*item.quantity,0);return {subtotal,delivery,total:subtotal+delivery,count:bag.reduce((n,item)=>n+item.quantity,0)};}
export function sanitizeBag(raw){if(!Array.isArray(raw))return [];return raw.filter(item=>item&&getProduct(item.product)&&Object.hasOwn(SIZES,item.size)&&Number.isInteger(item.quantity)&&item.quantity>0&&item.quantity<=9&&typeof item.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(item.date)&&!Number.isNaN(Date.parse(item.date))&&deliveryFor(item.zip).ok).slice(0,30).map((item,index)=>({id:`item-${index}`,product:item.product,size:item.size,quantity:item.quantity,vase:item.vase===true,zip:String(item.zip).trim(),date:item.date,message:String(item.message||'').slice(0,240),color:getProduct(item.product).colors.includes(item.color)?item.color:'original',description:typeof item.description==='string'?item.description.trim().slice(0,1000):''}));}
export function filterProducts(filters={},now=new Date()){const nextDate=datesFor(PRODUCTS[0],now).find(d=>!d.reason)?.date;return PRODUCTS.filter(p=>(!filters.occasion||p.occasions.includes(filters.occasion))&&(!filters.budget||p.price<=Number(filters.budget))&&(!filters.color||p.color===filters.color)&&(!filters.availability||(filters.availability==='next'?!dateStatus(nextDate,p,now):datesFor(p,now).some((d,index)=>!d.reason&&index<6))));}
export function recommend({occasion,style,budget}){const affordable=PRODUCTS.filter(p=>p.price<=Number(budget));return affordable.map(p=>({p,score:(p.occasions.includes(occasion)?2:0)+(p.style===style?3:0)})).sort((a,b)=>b.score-a.score||a.p.price-b.p.price).slice(0,2).map(item=>item.p);}
